        host=owner.Get("_context_host").As<Container>();host.AddChild(new Control{SizeFlagsHorizontal=Control.SizeFlags.ExpandFill});if(main_layer(owner)==null||tool is not "move" and not "rect_select" and not "lasso"){var size=Document(owner).Get("canvas_size").AsVector2I();var info=new Label{Text=size.X+" × "+size.Y};info.AddThemeColorOverride("font_color",new Color("8199ad"));host.AddChild(info);}
